package com.ggiova.gallery.data;

import java.time.Instant;
import java.time.LocalDateTime;

/**
 * Represents one item, as in, an image or video.
 *
 * @param id          Unique autogenerated long identification.
 * @param hash        of the file.
 * @param sizeBytes   Non-nullable size in bytes.
 * @param width       Non-nullable width of the file.
 * @param height      Non-nullable height of the file.
 * @param durationMs  Nullable, for videos only.
 * @param title       of the file.
 * @param description of the file.
 * @param favorite    determines if the file is favorite.
 * @param reviewed    determines if the file has been reviewed. For when files are automatically added instead of uploaded by the user.
 * @param createdAt   datetime it was uploaded at
 * @param takenAt     datetime it was taken at
 */
public record Item(
        long id,                    // non-nullable
        String hash,                // non-nullable
        long sizeBytes,             // non-nullable     bound: >0
        int width,                  // non-nullable     bound: >0
        int height,                 // non-nullable     bound: >0
        Long durationMs,            // nullable
        String title,               // non-nullable     default: ""
        String description,         // non-nullable     default: ""
        boolean favorite,           // non-nullable     default: false
        boolean reviewed,           // non-nullable     default: false
        Instant createdAt,          // non-nullable     default: today
        LocalDateTime takenAt       // nullable
) {
    public Item {
        if (hash == null) {
            throw new NullPointerException("hash cannot be null");
        }
        if (sizeBytes <= 0) {
            throw new IllegalArgumentException("sizeBytes must be > 0");
        }
        if (width <= 0) {
            throw new IllegalArgumentException("width must be > 0");
        }
        if (height <= 0) {
            throw new IllegalArgumentException("height must be > 0");
        }
        if (durationMs != null && durationMs <= 0) {
            throw new IllegalArgumentException("durationMs must be > 0");
        }
        if (title == null) {
            title = "";
        }
        if (description == null) {
            description = "";
        }
        if (createdAt == null) {
            throw new NullPointerException("createdAt cannot be null");
        }
    }
}
